func TestOnlyTheSigningGateIsReadFromLivePolicy(t *testing.T) {
	body := validateBundleAttestationWithBody(t)
	seen, err := livePolicyFields(body)
	if err != nil {
		t.Fatal(err)
	}
	if !seen["RequireSignedAttestations"] {
		t.Error("the signing requirement is no longer read from the live policy — a bundle sealed before a project started requiring signatures is now permanently exempt from it")
	}
	delete(seen, "RequireSignedAttestations")
	if !seen["DelegatedReview"] {
		t.Error("the delegated run proof bar is no longer read live; prefix-only identities could remain exempt after explicit opt-in")
	}
	delete(seen, "DelegatedReview")
	for field := range seen {
		t.Errorf("policy.%s is read live while judging a sealed bundle: seal it into the bundle's gates, or record here why it is an additional explicit trust exception", field)
	}
}

// The other side of the same contract: the gates a bundle carries are the ones
// the validator consults. A gate added to the struct and never read is a
// setting that seals and does nothing.
func TestEverySealedGateIsConsulted(t *testing.T) {
	body := validateBundleAttestationWithBody(t)
	for _, gate := range []string{"AllowApprovedWithReservations", "AcceptedRiskSeverities", "AllowCriterionReuse"} {
		if !strings.Contains(body, "SealedGates()."+gate) {
			t.Errorf("%s is sealed into the bundle and never consulted while judging one", gate)
		}
	}
	text := renderReviewBriefBody(fixedBriefBundle(), ReviewBriefKindReview, reviewBriefTemplates[ReviewBriefKindReview], "", nil, &ReviewRound{Number: 2}, true, nil)
	for _, phrase := range []string{"the identifier listed under Findings to account for, which carries its round, for example R2-F1, never a bare F1", "a finding you report now takes an `id` that no earlier round used"} {
		if !strings.Contains(text, phrase) {
			t.Errorf("the brief of round 2 does not state the rule behind \"prior finding id is not a unique carried identifier\": %q", phrase)
		}
	}
	earlier := renderReviewBriefBody(fixedBriefBundle(), ReviewBriefKindReview, reviewBriefTemplateConclusions, "", nil, &ReviewRound{Number: 2}, true, nil)
	if strings.Contains(earlier, "never a bare F1") {
		t.Error("review-brief/4 changed under its version: the rule belongs to review-brief/5 and later")
	}
}

// Spec pose-review-readiness-before-seal R4: the current brief asks the
// reviewer to check its draft before finishing; /7 never did.
func TestTheCurrentBriefAsksForTheDraftCheck(t *testing.T) {
	const step = "pipe it to `\"$POSE_REVIEW_CLI\" review draft-check --draft -`"
	current := renderReviewBriefBody(fixedBriefBundle(), ReviewBriefKindReview, reviewBriefTemplates[ReviewBriefKindReview], "", nil, &ReviewRound{Number: 1}, true, nil)
	if !strings.Contains(current, step) {
		t.Fatal("the current review brief does not ask for the draft check")
	}
	earlier := renderReviewBriefBody(fixedBriefBundle(), ReviewBriefKindReview, reviewBriefTemplateAllNotApplicable, "", nil, &ReviewRound{Number: 1}, true, nil)
	if strings.Contains(earlier, step) {
		t.Fatal("review-brief/7 changed under the runs briefed with it")
